 function draw(id,series,{rank=false,selectedDate,pick}={}){const svg=$(id),W=Math.max(320,Math.round(svg.getBoundingClientRect().width||1000)),H=300,L=48,R=20,T=22,B=35;svg.setAttribute('viewBox',`0 0 ${W} ${H}`);$(id+'Inspect')?.remove();const dates=[...new Set(series.flatMap(s=>s.points.map(p=>p.date)))].sort(),values=series.flatMap(s=>s.points.map(p=>p.value)).filter(finite);if(!dates.length||!values.length){svg.innerHTML=`<text x="${W/2}" y="140" fill="currentColor" text-anchor="middle">Keine vergleichbaren Werte.</text>`;return;}const lo=rank?1:Math.min(0,...values),hi=rank?Math.max(2,series.length):Math.max(1,...values),span=Date.parse(dates.at(-1))-Date.parse(dates[0])||1,x=d=>L+(Date.parse(d)-Date.parse(dates[0]))/span*(W-L-R),y=v=>rank?T+(v-lo)/(hi-lo||1)*(H-T-B):T+(hi-v)/(hi-lo||1)*(H-T-B);let out=[0,.25,.5,.75,1].map(f=>{const v=lo+(hi-lo)*f;return `<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="var(--line)"/><text x="${L-9}" y="${y(v)+4}" fill="currentColor" text-anchor="end" font-size="11">${num(v,1)}</text>`;}).join('');series.forEach((s,i)=>{let path='',pen=false,mask=null;for(const p of s.points){if(!finite(p.value)){pen=false;continue;}if(mask!==p.components)pen=false;path+=(pen?'L':'M')+x(p.date).toFixed(2)+' '+y(p.value).toFixed(2)+' ';pen=true;mask=p.components;}out+=`<path d="${path}" fill="none" stroke="${colors[i%colors.length]}" stroke-width="${i===series.length-1&&!rank?2.7:2.2}"/>`;});series.forEach((s,i)=>{if(s.points.length<=60)out+=s.points.filter(p=>finite(p.value)).map(p=>'<circle cx="'+x(p.date)+'" cy="'+y(p.value)+'" r="2.3" fill="'+colors[i%colors.length]+'" aria-hidden="true"/>').join('');});[dates[0],dates.at(-1)].forEach((d,i)=>out+=`<text x="${x(d)}" y="${H-9}" fill="currentColor" font-size="11" text-anchor="${i?'end':'start'}">${d.slice(0,10)}</text>`);svg.innerHTML=out;window.CockpitCharts?.bind(svg,series,{x,selectedDate,unit:rank?' Rang':'',pick});}
