 if(metric==='partial'){const coverage=r.coveragePoints??p.coveragePoints;return coverage>0&&finite(r.partialPoints)?r.partialPoints:null;}
 if(metric==='total')return (r.complete||r.coveragePoints===100)&&finite(r.total)?r.total:null;
 if(metric==='coverage')return finite(r.coveragePoints)?r.coveragePoints:null;
 if(metric==='price'||metric==='return'||metric==='adjustedReturn')return finite(p.price)?p.price:null;
 if(metric==='pe')return finite(p.peTTM)?p.peTTM:finite(input.peApprox)?input.peApprox:null;
 if(metric==='ytdPricePct')return finite(p.ytdPricePct)?p.ytdPricePct:null;
