 const historical={revenueGrowth:'quarterRevenueGrowth',operatingMargins:'operatingMarginTTM',returnOnEquity:'returnOnEquity',priceToBook:'priceToBook',earningsGrowth:'earningsGrowth',trailingEps:'epsQuarterSum'};
