function lineSegments(points){const out=[];for(const source of [...new Set(points.map(p=>p.source))]){let current=[];for(const p of points.filter(p=>p.source===source).sort((a,b)=>a.date.localeCompare(b.date))){const prev=current.at(-1);if(!finite(p.value)){if(current.length)out.push(current);current=[];continue;}if(prev&&(p.signature!==prev.signature||Date.parse(p.date)-Date.parse(prev.date)>(p.source==='retrospective'?70:12)*86400000)){out.push(current);current=[];}current.push(p);}if(current.length)out.push(current);}return out;}
