 const view=document.createElement('section');view.id='comparison';view.className='view';view.innerHTML=`<div class="panel"><div class="dashboard-eyebrow">Aktien, Branchen und Indizes</div><h2>Dein Vergleich</h2><p class="dashboard-muted">Wähle eine Kennzahl und ergänze beliebig viele Vergleichspartner.</p><div class="unified-controls"><label>Kennzahl<select id="unifiedMetric" aria-label="Vergleich Kennzahl"></select></label><label>Ansicht<select id="unifiedMode"><option value="history">Historischer Verlauf</option><option value="current">Aktueller Stand</option></select></label><label>Zeitraum<select id="unifiedRange"><option value="1M">1 Monat</option><option value="3M">3 Monate</option><option value="6M">6 Monate</option><option value="YTD">Seit Jahresbeginn</option><option value="1Y">1 Jahr</option><option value="3Y">3 Jahre</option><option value="5Y" selected>5 Jahre</option><option value="all">Alle Daten</option></select></label><label>Währung<select id="unifiedCurrency"><option value="EUR">EUR</option><option value="USD">USD</option></select></label></div><div id="unifiedSelections" class="unified-selections"></div><div class="hub-actions"><button id="unifiedAddStock" class="secondary">＋ Aktie</button><button id="unifiedAddBenchmark" class="secondary">＋ Benchmark</button><button id="unifiedAddSector" class="secondary">＋ Branche</button></div><p id="unifiedStatus" role="status" class="hub-status">Daten werden geladen …</p><div id="unifiedSourceLegend" class="unified-source-legend"><span><i class="unified-dashed"></i> Historisch rückgerechnet</span><span><i></i> Tatsächlich erfasst</span></div><svg id="unifiedChart" viewBox="0 0 1000 330" role="img" aria-label="Gemeinsamer Vergleich mit gekennzeichneter Datenherkunft"></svg><div id="unifiedInspect" role="status" class="hub-status"></div><div id="unifiedLegend" class="unified-legend"></div><p id="unifiedNotes" class="hub-status"></p><div class="unified-explanation"><b>Was bedeuten die Linien?</b><p><b>Gestrichelt:</b> Wir berechnen den Wert heute aus historischen Daten. Das ist eine Rückrechnung, kein damals gespeicherter Score.</p><p><b>Durchgezogen:</b> Diesen Wert hat unser System am betreffenden Tag tatsächlich berechnet und gespeichert.</p><p>Beides steht in einem Chart. Unterschiedliche Kategorien, Modelle und Datenlücken werden nicht nahtlos verbunden. Teilpunkte werden niemals auf 100 hochgerechnet. Kurse und Renditen stammen aus Marktdaten und haben diese Score-Unterscheidung nicht.</p></div><details id="unifiedDataDetails" data-info-ready="true"><summary>Werte & Export</summary><div class="tbl"><table><thead><tr><th>Auswahl</th><th>Datum</th><th>Wert</th><th>Herkunft</th><th>Score-Abdeckung</th></tr></thead><tbody id="unifiedRows"></tbody></table></div><button id="unifiedCsv" class="secondary">Vergleich als CSV</button></details></div>`;$('overview').parentNode.append(view);
