  function choose(value){if(selected.some((other,j)=>j!==i&&other.type===item.type&&other.key===value&&value)){select.value=item.key;$('unifiedStatus').textContent='Diese Auswahl ist bereits im Vergleich enthalten.';return;}item.key=value;persist();render();}
