 const storedComparisons=document.createElement('details');storedComparisons.dataset.infoReady='true';storedComparisons.innerHTML='<summary>Gespeicherte Vergleiche</summary><p class="hub-status">Deine letzte Auswahl wird automatisch in diesem Browser gespeichert. Frühere benannte Vergleiche kannst du hier weiter öffnen.</p><div id="unifiedOldPresets" class="hub-actions"></div>';view.firstElementChild.append(storedComparisons);
